contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(this));
        // caller (this contract) is the initial owner, so call must not revert
        c.transferOwnership(newOwner);
        address nowOwner = c.owner();
        assert(nowOwner == newOwner);
    }
    receive() external payable {}
}
